class Cat extends StatelessWidget{final String cat;final List props;final String gt,gc;Cat({required this.cat,required this.props,required this.gt,required this.gc});@override Widget build(BuildContext c){var f=props.where((e)=>e['cat']==cat).toList();return Scaffold(appBar:AppBar(title:Text('$cat - ${f.length}'),backgroundColor:Color(0xFF2E7D32)),body:f.isEmpty?Center(child:Text('Wala pay $cat - Ikaw una mag post + picture!')):ListView.builder(itemCount:f.length,itemBuilder:(c,i){var p=f[i];return Card(margin:EdgeInsets.all(10),child:Column(children:[Image.network(p['img'],height:180,width:double.infinity,fit:BoxFit.cover),ListTile(title:Text(p['title']),subtitle:Text('${p['loc']} - ₱${p['price']}')),Row(children:[Expanded(child:OutlinedButton.icon(icon:Icon(Icons.chat),label:Text('Chat'),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(owner:p['owner'],title:p['title']))))),Expanded(child:ElevatedButton(onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>Pay(price:p['price'],com:(p['price']*0.15).toInt(),gt:gt,gc:gc)),child:Text('Book')))])]));}));}}

class Chat extends StatefulWidget{final String owner,title;Chat({required this.owner,required this.title});@override State<Chat> createState()=>_ChatS();}
class _ChatS extends State<Chat>{List<String> msgs=[];var ctrl=TextEditingController();@override void initState(){super.initState();msgs=['Hello ${widget.owner}, available pa ${widget.title}?','Yes boss available! GCash/GoTyme ta!'];}@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text('Chat ${widget.owner} - TINUOD NA!'),backgroundColor:Color(0xFF2E7D32)),body:Column(children:[Expanded(child:ListView.builder(itemCount:msgs.length,itemBuilder:(c,i)=>Align(alignment:i%2==0?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:EdgeInsets.all(8),padding:EdgeInsets.all(12),decoration:BoxDecoration(color:i%2==0?Color(0xFF2E7D32):Colors.grey.shade200,borderRadius:BorderRadius.circular(15)),child:Text(msgs[i],style:TextStyle(color:i%2==0?Colors.white:Colors.black)))))),Padding(padding:EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:ctrl,decoration:InputDecoration(hintText:'Maka-chat tinuod! Type...',border:OutlineInputBorder(borderRadius:BorderRadius.circular(20))))),SizedBox(width:8),CircleAvatar(backgroundColor:Color(0xFF2E7D32),child:IconButton(icon:Icon(Icons.send,color:Colors.white),onPressed:(){if(ctrl.text.isNotEmpty){setState(()=>msgs.add(ctrl.text));ctrl.clear();Future.delayed(Duration(seconds:1),()=>setState(()=>msgs.add('Copy boss! Mo-reply ko - ${widget.owner} - GCash ta!')));}}))]))]));}}

