Border())),SizedBox(height:8),TextField(controller:pr,decoration:InputDecoration(labelText:'Price - Ex: 15000',border:OutlineInputBorder()),keyboardType:TextInputType.number),SizedBox(height:15),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Color(0xFFFF6B00),padding:EdgeInsets.all(15)),onPressed:(){if(t.text.isEmpty){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Butangi Title!')));return;}widget.onAdd({'title':t.text,'price':int.tryParse(pr.text)??15000,'loc':'Davao','cat':cat,'owner':'Ikaw','img':img.text});Navigator.pop(c);ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('✅ NA-POST NA UBAN ANG PICTURE - MAKULAY!')));},child:Text('I-POST NA - MAKULAY!',style:TextStyle(fontSize:16)))])));}}

